custom_qss:
/* ============================================================
   AZURE — electric blue on deep navy. Cool single hue, cool-white
   text. Rounded, borderless. Near-vertical light-fall everywhere.
   Signature: thick pill tabs and a bright sheen stop baked high in
   each vertical gradient, so surfaces read as lit from above.
   Uppercase letter-spaced dock + group labels.
   ============================================================ */

* {
    border: none; background-color: transparent !important; color: #e2ecf7;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important; border: none;
}

QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #12203a, stop:0.4 #0a1220, stop:0.75 #070d18, stop:1 #0c1526) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1,
        stop:0 #12203a, stop:0.5 #0c1424, stop:1 #060b14) !important;
}

QMenuBar { background: transparent !important; }
QMenuBar::item { padding: 5px 13px; border-radius: 8px; background: transparent !important; color: #6c82a3; }
QMenuBar::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #1b3a68, stop:1 #27538f) !important; color: #e2ecf7; }
QMenuBar::item:disabled { color: #445570; }

QMenu {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #14223a, stop:1 #0a1120) !important;
    border-radius: 14px; padding: 7px;
}
QMenu::item { padding: 7px 26px 7px 14px; border-radius: 9px; background: transparent !important; color: #e2ecf7; }
QMenu::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:1 #12325e) !important; color: #ffffff !important; }
QMenu::item:disabled { color: #445570; }
QMenu::separator { height: 1px; background: #1c2c48; margin: 6px 10px; border-radius: 1px; }

QToolBar { background: transparent !important; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #1c2c48; width: 2px; margin: 6px 5px; border-radius: 1px; }
QToolBar QToolButton, QToolButton {
    background: transparent !important; padding: 6px 10px; border-radius: 9px; color: #6c82a3;
}
QToolBar QToolButton:hover, QToolButton:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1b2c48, stop:1 #101c30) !important; color: #7ab8ff; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed, QToolButton:checked, QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:1 #12325e) !important; color: #ffffff !important;
}

QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1a2c48, stop:0.35 #14223a, stop:1 #0f1a2e) !important;
    border-radius: 13px; padding: 8px 22px; color: #e2ecf7; font-weight: 600;
}
QPushButton:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #27538f, stop:0.12 #3b8ef0, stop:0.55 #2a6fc0, stop:1 #12325e) !important; color: #ffffff !important; }
QPushButton:pressed { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #0f1a2e, stop:0.5 #1a2c48, stop:0.9 #3b8ef0, stop:1 #12325e) !important; color: #ffffff !important; }
QPushButton:checked { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:0.5 #2a6fc0, stop:1 #7ab8ff) !important; color: #ffffff !important; }
QPushButton:disabled { background: #0c1424 !important; color: #445570 !important; }

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #14223a, stop:1 #0a1120) !important;
    border-radius: 11px; padding: 6px 12px; color: #7ab8ff;
    selection-background-color: #3b8ef0; selection-color: #ffffff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1c2c48, stop:1 #14223a) !important; color: #ffffff !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #445570 !important; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1a2c48, stop:1 #0f1a2e) !important;
    border-radius: 11px; padding: 6px 12px; color: #e2ecf7;
}
QComboBox:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #27395c, stop:1 #14223a) !important; }
QComboBox:focus { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #3b8ef0, stop:1 #12325e) !important; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #14223a, stop:1 #0a1120) !important;
    border-radius: 13px; padding: 6px; selection-background-color: #3b8ef0; selection-color: #ffffff;
}

QCheckBox, QRadioButton { color: #e2ecf7; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator {
    width: 20px; height: 20px; border-radius: 6px;
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1c2c48, stop:1 #0f1a2e) !important;
}
QRadioButton::indicator { border-radius: 10px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #27395c, stop:1 #1c2c48) !important; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: qlineargradient(x1:0, y1:0, x2:1, y2:1, stop:0 #3b8ef0, stop:1 #12325e) !important; }

QTabBar::tab { background: transparent !important; color: #6c82a3; padding: 9px 18px; border-radius: 11px; margin: 0 1px; }
QTabBar::tab:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #16243d, stop:1 #0c1424) !important; color: #7ab8ff; }
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:0.5 #2a6fc0, stop:1 #7ab8ff) !important;
    color: #ffffff !important; font-weight: 700; letter-spacing: 0.5px;
}
QTabWidget::pane { border: none; background: #0a1220; }

QDockWidget { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #12203a, stop:0.6 #0f1a2e, stop:1 #0c1424) !important; border: none; }
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #16243d, stop:1 #0c1424) !important;
    border-radius: 8px; margin: 3px; padding: 7px 11px;
    color: #9fb4d0; font-size: 11px; font-weight: 700; letter-spacing: 1.5px;
}
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: none; border-radius: 6px; padding: 3px; icon-size: 13px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #1b2c48 !important; }

QGroupBox { background: transparent !important; border: none; border-radius: 12px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 9px; color: #7ab8ff; font-weight: 700; letter-spacing: 1.2px; background: #0a1220; }

QAbstractItemView { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #0c1424, stop:1 #070d18) !important; border: none; border-radius: 12px; outline: none; alternate-background-color: #0a1120; selection-background-color: #3b8ef0; selection-color: #ffffff; }
QAbstractItemView::item { padding: 6px 10px; border: none; color: #e2ecf7; border-radius: 8px; }
QAbstractItemView::item:hover { background: #14223a !important; }
QAbstractItemView::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:1 #12325e) !important; color: #ffffff !important; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #0c1424 !important; border: none; padding: 7px 11px; color: #6c82a3; font-size: 11px; font-weight: 700; letter-spacing: 1px; }

QScrollBar:vertical { background: transparent; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #27395c, stop:1 #1c2c48) !important; border-radius: 6px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3b8ef0, stop:1 #12325e) !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: transparent; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #27395c, stop:1 #1c2c48) !important; border-radius: 6px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #3b8ef0, stop:1 #12325e) !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #070d18; border: none; height: 6px; border-radius: 3px; }
QSlider::sub-page:horizontal { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #12325e, stop:1 #3b8ef0) !important; border-radius: 3px; }
QSlider::add-page:horizontal { background: #070d18; border-radius: 3px; }
QSlider::handle:horizontal { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #7ab8ff, stop:1 #3b8ef0) !important; width: 16px; height: 16px; margin: -6px 0; border: none; border-radius: 9px; }
QSlider::handle:horizontal:hover { background: #ffffff !important; }
QSlider::groove:vertical { background: #070d18; border: none; width: 6px; border-radius: 3px; }
QSlider::sub-page:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #12325e, stop:1 #3b8ef0) !important; border-radius: 3px; }
QSlider::handle:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #7ab8ff, stop:1 #3b8ef0) !important; width: 16px; height: 16px; margin: 0 -6px; border: none; border-radius: 9px; }

QProgressBar { background: #070d18; border: none; border-radius: 8px; text-align: center; color: #9fb4d0; font-size: 11px; min-height: 15px; }
QProgressBar::chunk { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #12325e, stop:0.5 #3b8ef0, stop:1 #7ab8ff) !important; border-radius: 6px; }

QStatusBar { background: transparent !important; color: #6c82a3; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #14223a, stop:1 #0a1120) !important; border: 1px solid #1c2c48; border-radius: 9px; padding: 7px 11px; color: #e2ecf7; }
QSplitter::handle { background: #1c2c48; border-radius: 2px; }
QSplitter::handle:hover { background: #3b8ef0; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #070d18 !important; border: none; border-radius: 12px; outline: none; }
